import { WIDGET_DURATION_MS, type WidgetId } from "@/components/overlay/widgetLifecycle";
import widgetSizes from "./widgetRecommendedSizes.json";

export type WidgetGuide = {
  id: WidgetId;
  name: string;
  group: "game" | "results" | "practice" | "community" | "production";
  summary: string;
  explanation: string;
  example: { headline: string; lines: readonly string[] };
  appears: string;
  needs: readonly string[];
  setup: readonly string[];
  check: string;
  troubleshooting: string;
  placement: string;
  recommendedSize: { width: number; height: number };
  /** All-in-one widgets also have an independently positionable widget URL. */
  source: "all-in-one" | "dedicated";
  settingsHref: string;
  related: readonly WidgetId[];
  /** Help article that explains where this widget's numbers come from. */
  helpSlug?: string;
};

export const WIDGET_GROUPS: readonly {
  id: WidgetGuide["group"];
  name: string;
  description: string;
}[] = [
  { id: "game", name: "Game intel", description: "Meet the opponent and turn your replay history into useful context." },
  { id: "results", name: "Results & session", description: "Make each result and the bigger session story easy to follow." },
  { id: "practice", name: "Practice", description: "Choose what to play and rehearse a timed build." },
  { id: "community", name: "Chat & community", description: "Bring chat, viewer decisions, and supporter recognition onto the stream." },
  { id: "production", name: "Stream production", description: "Run breaks, countdowns, recaps, and broadcast graphics from your dock." },
];

const OVERLAY_SETTINGS = "/settings?tab=overlay";
const liveAgent = "A paired desktop agent running while you play StarCraft II.";
const replayHistory = "Uploaded, processed replays on your account; richer history produces richer cards.";
const configuredChat = "At least one platform enabled in Multi-platform chat, with Save chat settings completed.";

function sourceSetup(name: string): readonly string[] {
  return [
    `Open Settings → Overlay → Widgets and enable ${name}.`,
    `Use Copy beside ${name} to copy its widget URL.`,
    "In OBS, add a Browser Source, paste the copied URL, and position it in your scene.",
    `Keep that source loaded, then press Test beside ${name} in Settings. During a live match, use Preview here instead for a local sample, or confirm Send anyway to show samples to viewers for about 20 seconds. Stop restores the real data.`,
  ];
}

function dockSetup(name: string, action: string): readonly string[] {
  return [
    `In Settings → Overlay, enable ${name} and use Copy beside its URL.`,
    "Paste it into a dedicated OBS Browser Source and position it in your scene.",
    "Copy Stream Dock from Settings → Chat & alerts → Stream Dock; in OBS add it under Docks → Custom Browser Docks.",
    action,
  ];
}

